import{_ as d,C as r,o as l,c as i,j as t,a,E as n,a2 as s}from"./chunks/framework.CdvW4CUT.js";const P=JSON.parse('{"title":"部署目标","description":"CertHub 的 75 个部署插件：主机、面板、集群、云 CDN、对象存储与通用自动化任务。","frontmatter":{"title":"部署目标","description":"CertHub 的 75 个部署插件：主机、面板、集群、云 CDN、对象存储与通用自动化任务。"},"headers":[],"relativePath":"docs/deploy.md","filePath":"docs/deploy.md","lastUpdated":null}'),c={name:"docs/deploy.md"};function h(p,e,u,b,m,S){const o=r("PluginGroups");return l(),i("div",null,[e[0]||(e[0]=t("h1",{id:"部署目标",tabindex:"-1"},[a("部署目标 "),t("a",{class:"header-anchor",href:"#部署目标","aria-label":'Permalink to "部署目标"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("证书签发后，按流水线配置下发到目标并自动重载服务。内置 "),t("strong",null,"75 个"),a("部署插件，按交付方式分成六类，同类共用一套代码，差别只是默认路径、endpoint 与几个参数。")],-1)),e[2]||(e[2]=t("h2",{id:"全部插件",tabindex:"-1"},[a("全部插件 "),t("a",{class:"header-anchor",href:"#全部插件","aria-label":'Permalink to "全部插件"'},"​")],-1)),n(o),e[3]||(e[3]=s('<h2 id="通用参数" tabindex="-1">通用参数 <a class="header-anchor" href="#通用参数" aria-label="Permalink to &quot;通用参数&quot;">​</a></h2><p>主机 / 中间件类插件的字段基本一致：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>主机授权</td><td>选一条 SSH 授权，决定传到哪台机器</td></tr><tr><td>证书路径 / 私钥路径</td><td>支持变量，例如 <code>/etc/nginx/ssl/{{cert.domain}}.crt</code></td></tr><tr><td>PFX 路径 / 密码</td><td>需要 IIS、Java 等场景时填，留空则不生成</td></tr><tr><td>重载命令</td><td>例如 <code>nginx -s reload</code>、<code>systemctl reload httpd</code>、<code>docker restart nginx</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">路径一定要带变量</p><p>同一台机器上放多张证书时，用 <code>{{cert.domain}}</code> 区分文件名，否则后一次部署会覆盖前一次。</p></div><h2 id="各类要点" tabindex="-1">各类要点 <a class="header-anchor" href="#各类要点" aria-label="Permalink to &quot;各类要点&quot;">​</a></h2><h3 id="主机-·-中间件" tabindex="-1">主机 · 中间件 <a class="header-anchor" href="#主机-·-中间件" aria-label="Permalink to &quot;主机 · 中间件&quot;">​</a></h3><p>覆盖远程主机（SSH / SFTP）、本机目录、Nginx、Apache、HAProxy、Tomcat、IIS、FTP、执行远程命令、ESXi。</p><ul><li>证书文件权限默认按 <code>644</code> 写入，私钥 <code>600</code>；服务账号不是 root 时注意目录属主。</li><li>IIS 走 Windows 远程，需要开启 WinRM 或对应接口。</li><li>「执行远程主机命令」适合插件没覆盖的服务：传完证书后自己写一条 <code>systemctl reload xxx</code>。</li></ul><h3 id="面板" tabindex="-1">面板 <a class="header-anchor" href="#面板" aria-label="Permalink to &quot;面板&quot;">​</a></h3><p>宝塔、1Panel、群晖 DSM、威联通 QTS、Proxmox VE、Nginx Proxy Manager、OpenWrt / iStoreOS、雷池 WAF、AcePanel、飞牛 NAS。</p><ul><li>面板类授权要能<strong>长期跑</strong>：两步验证别只留「验证码」字段（30 秒就过期），要留 Base32 密钥由系统现算，或者用群晖的「设备 ID」。</li><li>宝塔 / 1Panel / NPM 支持<strong>多站点选择</strong>，一次部署可以覆盖同一面板上的多个站点。</li><li>群晖可以设「默认证书」并自定义证书名称（<code>asDefault</code> / <code>certDesc</code>），详见 <a href="./access.html">授权管理</a>。</li></ul><h3 id="云-cdn" tabindex="-1">云 CDN <a class="header-anchor" href="#云-cdn" aria-label="Permalink to &quot;云 CDN&quot;">​</a></h3><p>阿里云 CDN / DCDN / 直播 / 点播 / SLB、腾讯云 CDN / EdgeOne / CLB、火山引擎 CDN / 直播、AWS CloudFront、Fastly、七牛、天翼云、京东云、多吉云、易盾 DCDN、括彩云、我爱云、又拍云、白山云、百度云、华为云、中国移动、金山云、雨云、UCloud 等，共 35 个。</p><p>流程都是「上传证书到证书中心 → 绑定到加速域名」，因此需要对应云厂商授权，且账号要有证书与 CDN 的操作权限。</p><h3 id="对象存储" tabindex="-1">对象存储 <a class="header-anchor" href="#对象存储" aria-label="Permalink to &quot;对象存储&quot;">​</a></h3><p>阿里云 OSS、腾讯云 COS、华为云 OBS、火山引擎 TOS、AWS S3、S3 兼容存储、Cloudflare R2、七牛 Kodo、UCloud US3。</p><ul><li>填 Endpoint、Access Key、Secret Key、Region，桶名在任务里选。</li><li>证书默认以 <code>application/x-pem-file</code> 写入，路径可自定义（例如 <code>ssl/{{cert.domain}}/fullchain.pem</code>）。</li></ul><h3 id="集群" tabindex="-1">集群 <a class="header-anchor" href="#集群" aria-label="Permalink to &quot;集群&quot;">​</a></h3><p>Kubernetes Secret / Ingress、阿里云 ACK、百度云 CCE、腾讯云 TKE。</p><ul><li>K8s 需要 API Server 地址、Token、命名空间，可选集群 CA 证书。</li><li>部署到 Ingress 时会同时更新 <code>tls.crt</code> / <code>tls.key</code>，并触发对应 Ingress 生效。</li></ul><h3 id="通用任务" tabindex="-1">通用任务 <a class="header-anchor" href="#通用任务" aria-label="Permalink to &quot;通用任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务</th><th>用途</th></tr></thead><tbody><tr><td>推送到自定义接口（Webhook）</td><td>把证书推给自有系统，由对端完成安装；支持鉴权 Token 与附加参数</td></tr><tr><td>证书发送到邮箱</td><td>把证书作为附件发出，适合人工分发</td></tr><tr><td>在主机执行脚本</td><td>插件没覆盖的场景，用脚本兜底</td></tr><tr><td>等待</td><td>在两个任务之间插入固定延时，适配生效较慢的平台</td></tr><tr><td>数据备份</td><td>把证书归档到指定位置，配合外部备份策略</td></tr></tbody></table><h2 id="部署失败怎么查" tabindex="-1">部署失败怎么查 <a class="header-anchor" href="#部署失败怎么查" aria-label="Permalink to &quot;部署失败怎么查&quot;">​</a></h2><ol><li>看日志里该任务的那一段（hover 任务卡 →「查看该任务日志」）。</li><li>目标站点还是旧证书？先确认<strong>证书库里的证书是新的</strong>，再确认路径与重载命令。</li><li>部分面板需要手动触发一次重载才生效；CDN 有几分钟的生效延迟。</li><li>权限问题最常见：写不进目录、<code>reload</code> 没有 sudo 权限、云账号只有读权限。</li></ol><p>更多见 <a href="./troubleshoot.html">故障排查</a>。</p>',25))])}const C=d(c,[["render",h]]);export{P as __pageData,C as default};
